import{H as e,Mt as t,ft as n,ut as r}from"./chunks/framework.DWfRCYNt.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"english/articles/1.md","filePath":"english/articles/1.md"}`),a={name:`english/articles/1.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<p>I want to create a mini ecosystem in my bedroom,But I don&#39;t know anything about ecology. So, I must learn about ecology.</p><p>But I am hungry now. I want to order some takeaway(takeout) meal with fish. But I didn&#39;t see any takeaway food with fish.</p><p>But I really want to eat it. I got dressed and prepared to go to a fish pond to catch some fish. I met a fisherman in this fishpond, He taught me some fishing techniques.</p><p>I also asked him some techniques, This knowledge happens to be useful for the mini ecosystem I&#39;m trying to build.</p><p>I&#39;m going home now. Because tomorrow is my workday.</p><p>Yes, Monday to Friday is my workdays，Saturday and Sunday is my holiday. I overcame the difficulties and created a mini ecosystem.</p><p>Later, the fisherman invited me to his home, He introduced me to one of his favorite fishes, which he said was his lifelong companion. Tell me how he became a fisherman overnight.</p><p>He took out his granddaughter&#39;s textbook again and asked me if had read them in my childhood.</p><p>Yes, I have read these books, and I have them in a bookstore near my hometown.</p><p>He showed me around his grandson&#39;s room, which had a computer and a cool keyboard that his grandson had handmade.</p><p>He also told me that he was a gentleman when he was younger.</p><p>What industry did you work in when you were younger?</p><p>I was a secret agent when I was younger, and she didn&#39;t know about my job when she wasn&#39;t my wife. At that time, we were not living together at the time, and we just used postcards to communicate.</p><p>So how did you get your wife&#39;s postcard?</p><p>postman.</p>`,15)]])}va